struct C2DVector { float X,Y; C2DVector(){} C2DVector(const C2DVector& p):X(p.X),Y(p.Y){} };
struct C2DBoxF { float TLX,TLY,BRX,BRY; C2DBoxF(){} C2DBoxF(const C2DBoxF& p):TLX(p.TLX),TLY(p.TLY),BRX(p.BRX),BRY(p.BRY){} };
struct C2DBoxI { long TLX,TLY,BRX,BRY; };
struct C2DCoordI { long X,Y; C2DCoordI(long x,long y):X(x),Y(y) {} };
struct CHoverable;
#pragma pointers_to_members(full_generality,single_inheritance)
union HoverSlot {
    void* Address;
    C2DVector* (CHoverable::*Vector)(C2DVector*) const;
    C2DBoxF* (CHoverable::*Bounds)(C2DBoxF*) const;
};
#ifdef _MSC_VER
FABLE_STATIC_ASSERT(sizeof(HoverSlot)==4);
#endif
struct CHoverable : ::CHoverable {
    bool IsHovered(C2DBoxI&) const;
};
bool CHoverable::IsHovered(C2DBoxI& mouse) const {
    C2DVector position; (this->*static_cast<const HoverSlot*>(__vftable)[122].Vector)(&position);
    C2DVector zoom; (this->*static_cast<const HoverSlot*>(__vftable)[123].Vector)(&zoom);
    C2DBoxF bounds; (this->*static_cast<const HoverSlot*>(__vftable)[24].Bounds)(&bounds);
    C2DCoordI topLeft(position.X+bounds.TLX,position.Y+bounds.TLY);
    C2DCoordI bottomRight(bounds.BRX*zoom.X+position.X,bounds.BRY*zoom.Y+position.Y);
    long x=mouse.TLX, y=mouse.TLY;
    if(x>=topLeft.X && x<bottomRight.X && y>=topLeft.Y && y<bottomRight.Y) return true;
    return false;
}
}


#include <stdio.h>
using namespace NUISystem;
struct HoverFixture : NUISystem::CHoverable {
    C2DVector Position,Zoom;
    C2DBoxF Box;
    mutable int Calls;
    C2DVector* PositionCall(C2DVector* p) const { if(Calls!=0) Calls=99; else ++Calls; *p=Position; return p; }
    C2DVector* ZoomCall(C2DVector* p) const { if(Calls!=1) Calls=99; else ++Calls; *p=Zoom; return p; }
    C2DBoxF* BoundsCall(C2DBoxF* p) const { if(Calls!=2) Calls=99; else ++Calls; *p=Box; return p; }
};
static bool check(HoverFixture& h,long x,long y,bool expected) {
    C2DBoxI mouse;mouse.TLX=x;mouse.TLY=y;mouse.BRX=-999;mouse.BRY=-999;
    h.Calls=0; return h.IsHovered(mouse)==expected && h.Calls==3;
}
int main() {
    HoverSlot slots[124];
    slots[122].Vector=static_cast<C2DVector* (NUISystem::CHoverable::*)(C2DVector*) const>(&HoverFixture::PositionCall);
    slots[123].Vector=static_cast<C2DVector* (NUISystem::CHoverable::*)(C2DVector*) const>(&HoverFixture::ZoomCall);
    slots[24].Bounds=static_cast<C2DBoxF* (NUISystem::CHoverable::*)(C2DBoxF*) const>(&HoverFixture::BoundsCall);
    HoverFixture h;h.__vftable=slots;
    h.Position.X=10.75f;h.Position.Y=-5.75f;h.Zoom.X=2.0f;h.Zoom.Y=3.0f;
    h.Box.TLX=1.0f;h.Box.TLY=2.0f;h.Box.BRX=5.0f;h.Box.BRY=4.0f;
    // Native truncation yields [11,20) x [-3,6); left/top deliberately do not scale.
    bool ok=check(h,11,-3,true) && check(h,19,5,true) && check(h,10,0,false) && check(h,20,0,false) && check(h,15,-4,false) && check(h,15,6,false);
    h.Position.X=-10.75f;h.Position.Y=-10.75f;h.Box.TLX=0;h.Box.TLY=0;h.Box.BRX=5;h.Box.BRY=5;h.Zoom.X=1;h.Zoom.Y=1;
    ok=ok && check(h,-10,-10,true) && check(h,-6,-6,true) && check(h,-5,-6,false) && check(h,-11,-6,false);
    h.Zoom.X=0;ok=ok && check(h,-10,-8,false);
    h.Zoom.X=-1;ok=ok && check(h,-12,-8,false);
    if(!ok) { printf("0055b8f0_TEST FAIL\n");return 1; }
    printf("0055b8f0_TEST PASS\n");return 0;
}

