    CHECK(g_group.IsRunnable(), "null hero falls back to other customers");
    CHECK(g_otherCalls == 1 && g_positionCalls[0] == 0 && g_gazeCalls == 1, "null hero does not read positions");

    setup(); g_hero = &g_heroThing; ((unsigned char*)&g_heroThing)[0x91] = 1; g_otherPeople = 1;
